fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let n = v.len();
    debug_assert!(n > 0);

    let mut lo: usize = 0;
    let mut hi: usize = n - 1; // inclusive

    while lo < hi {
        // mid in [lo, hi)
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            // k must be in (mid, hi]
            lo = mid + 1;
        } else {
            // k must be in [lo, mid]
            hi = mid;
        }
    }

    // With the problem's guarantee that k appears at least once,
    // the narrowed index must be an occurrence of k.
    debug_assert!(lo < n && v[lo] == k);
    lo
}